# ============================================================================ #
# BUILD STUFF — a real "from nothing" track: bash → files → run your own program
# ============================================================================ #

SHELL_STAGES = ["Meet the Terminal", "Folders & Paths", "Make & Inspect Files",
                "Write & Read", "Pipes & Search", "Copy, Move, Delete",
                "Run & Build", "Shells & Tools"]

# A tiny, deterministic fake filesystem so the learner can practice REAL bash
# (pwd / ls / mkdir / cd / touch / cat / echo / grep / pipes / chmod / …)
# WITHOUT touching the real disk. Every command is safe to run forever.
class ShellFS:
    """A sandboxed home directory the learner fills up over the course.

    `dirs` is a set of absolute directory paths; `files` maps an absolute path
    to its text content; `executable` marks files that `chmod +x` made runnable.
    `latest` remembers the last changed path so the file tree can highlight it.
    `history` records every command line, so `history` can list them back."""

    def __init__(self):
        self.home = "/home/you"
        self.cwd = self.home
        self.dirs = {"/", "/home", "/home/you"}
        self.files = {}
        self.executable = set()
        self.latest = None
        self.history: list[str] = []

    # -- path helpers ------------------------------------------------------ #
    def _resolve(self, path: str) -> str:
        while path.startswith("./"):
            path = path[2:]
        if path in ("", ".", "~"):
            return self.home
        if path == "..":
            return "/" if self.cwd == "/" else (self.cwd.rsplit("/", 1)[0] or "/")
        if path == "/":
            return "/"
        if path.startswith("/"):
            return path.rstrip("/") or "/"
        return (self.cwd.rstrip("/") + "/" + path).rstrip("/") or "/"

    def _children(self, path: str) -> list:
        base = path.rstrip("/") + "/"
        names = set()
        for d in self.dirs:
            if d.startswith(base) and d != path:
                rest = d[len(base):]
                if "/" not in rest:
                    names.add((rest, "dir"))
        for f in self.files:
            if f.startswith(base):
                rest = f[len(base):]
                if "/" not in rest:
                    names.add((rest, "file"))
        return sorted(names)

    def tree(self):
        """(indent, label, full_path, kind) from home down — for the live tree."""
        out = [(0, self.home + "/", self.home, "dir")]
        def walk(path, depth):
            for name, kind in self._children(path):
                full = path.rstrip("/") + "/" + name
                out.append((depth + 1, name + ("/" if kind == "dir" else ""), full, kind))
                if kind == "dir":
                    walk(full, depth + 1)
        walk(self.home, 0)
        return out

    def _expand(self, args):
        """Expand `*` globs against the cwd's names (no match → keep literal)."""
        out = []
        for a in args:
            if "*" in a:
                rx = "^" + re.escape(a).replace(r"\*", ".*") + "$"
                m = [n for n, _ in self._children(self.cwd) if re.match(rx, n)]
                out.extend(m if m else [a])
            else:
                out.append(a)
        return out

    def _read_lines(self, files, stdin_lines):
        """Read lines from files (glob-expanded) or stdin if no files given.
        Returns None on a missing/unreadable file (caller turns it into an error)."""
        if not files:
            return list(stdin_lines or [])
        lines = []
        for a in self._expand(files):
            p = self._resolve(a)
            if p in self.files:
                lines.extend(self.files[p].rstrip("\n").split("\n"))
            else:
                return None
        return lines

    # -- the public entry point (handles pipes) ---------------------------- #
    def run(self, cmdline: str, stdin_lines=None):
        """Run one line of bash. Returns (out_lines, err_lines)."""
        cmdline = cmdline.strip()
        if not cmdline:
            return [], []
        self.history.append(cmdline)
        if "|" in cmdline:
            data = stdin_lines
            for stage in [s.strip() for s in cmdline.split("|")]:
                out, err = self._run_one(stage, data)
                if err:
                    return out, err
                data = out
            return data, []
        return self._run_one(cmdline, stdin_lines)

    def _run_one(self, cmdline, stdin_lines=None):
        """One command (no pipes), with `>` / `>>` redirect stripped first."""
        cmdline = cmdline.strip()
        if not cmdline:
            return [], []
        target = None
        append = False
        if " >> " in cmdline:
            cmdline, target = cmdline.rsplit(" >> ", 1)
            append = True
        elif " > " in cmdline:
            cmdline, target = cmdline.rsplit(" > ", 1)
        out, err = self._dispatch(cmdline, stdin_lines)
        if target is not None and not err:
            tp = self._resolve(target.strip())
            if tp in self.dirs:
                return [], [f"bash: {target.strip()}: Is a directory"]
            body = "\n".join(out) + ("\n" if out else "")
            if append:
                self.files[tp] = self.files.get(tp, "") + body
            else:
                self.files[tp] = body
            self.latest = tp
            return [], []
        return out, err

    def _dispatch(self, cmdline, stdin_lines=None):
        parts = cmdline.split()
        if not parts:
            return [], []
        cmd = parts[0]
        args = parts[1:]
        if cmd == "echo":
            text = cmdline[4:].strip()
            if len(text) >= 2 and text[0] in ('"', "'") and text[-1] == text[0]:
                text = text[1:-1]
            return [text], []
        if cmd == "pwd":
            return [self.cwd], []
        if cmd == "whoami":
            return ["you"], []
        if cmd == "clear":
            return ["__CLEAR__"], []
        if cmd == "history":
            return [f"{i+1:>3}  {c}" for i, c in enumerate(self.history[-15:])], []
        if cmd == "ls":
            return self._ls(args), []
        if cmd == "mkdir":
            return self._mkdir(args)
        if cmd == "cd":
            return self._cd(args)
        if cmd == "touch":
            return self._touch(args)
        if cmd == "cat":
            return self._cat(args, stdin_lines)
        if cmd in ("head", "tail"):
            return self._head_tail(cmd, args, stdin_lines)
        if cmd == "wc":
            return self._wc(args, stdin_lines)
        if cmd == "grep":
            return self._grep(args, stdin_lines)
        if cmd == "python3":
            return self._python(args)
        if cmd == "mv":
            return self._mv(args)
        if cmd == "cp":
            return self._cp(args)
        if cmd == "rm":
            return self._rm(args)
        if cmd == "chmod":
            return self._chmod(args)
        if cmd in ("man", "help", "--help"):
            return ["commands:  pwd  ls  mkdir  cd  touch  cat  echo  head  tail  wc  grep  "
                    "python3  mv  cp  rm  chmod  whoami  clear  history"], []
        if cmd.startswith("./") or cmd.startswith("/"):
            return self._run_executable(cmd)
        return [], [f"{cmd}: command not found"]

    # -- individual commands ------------------------------------------------ #
    def _human(self, n):
        if n >= 1024:
            return f"{round(n / 1024, 1)}K"
        return f"{n}B"

    def _ls(self, args):
        flags = [a for a in args if a.startswith("-") and len(a) > 1]
        pos = [a for a in args if not (a.startswith("-") and len(a) > 1)]
        show_hidden = any("a" in f for f in flags)
        long = any("l" in f for f in flags)
        human = any("h" in f for f in flags)
        if pos:
            names = set()
            for p in pos:
                if "*" in p:
                    rx = "^" + re.escape(p).replace(r"\*", ".*") + "$"
                    names.update((n, k) for n, k in self._children(self.cwd) if re.match(rx, n))
                else:
                    full = self._resolve(p)
                    if full in self.dirs:
                        names.add((p.rstrip("/") + "/", "dir"))
                    elif full in self.files:
                        names.add((p, "file"))
            names = sorted(names)
        else:
            names = self._children(self.cwd)
        if not show_hidden:
            names = [(n, k) for n, k in names if not n.startswith(".")]
        if not names:
            return []
        if long:
            out = []
            for name, kind in names:
                if kind == "dir":
                    out.append(f"drwxr-xr-x  2 you  you  4096  Sep  7 09:00  {name}/")
                else:
                    size = len(self.files.get(self._resolve(name), ""))
                    mode = "-rwxr-xr-x" if self._resolve(name) in self.executable else "-rw-r--r--"
                    s = self._human(size) if human else f"{size:>5}"
                    out.append(f"{mode}  1 you  you  {s}  Sep  7 09:00  {name}")
            return out
        return [name + ("/" if kind == "dir" else "") for name, kind in names]

    def _mkdir(self, args):
        parents = "-p" in args
        targets = [a for a in args if not a.startswith("-")]
        if not targets:
            return [], ["mkdir: missing operand"]
        out = []
        for a in targets:
            p = self._resolve(a)
            if (p in self.dirs or p in self.files) and not parents:
                out.append(f"mkdir: cannot create directory '{a}': File exists")
                continue
            if parents:
                cur = "/"
                for seg in p.strip("/").split("/"):
                    cur = (cur.rstrip("/") + "/" + seg).rstrip("/") or "/"
                    self.dirs.add(cur)
            else:
                self.dirs.add(p)
            self.latest = p
        return out, []

    def _cd(self, args):
        if not args:
            self.cwd = self.home
            return [], []
        p = self._resolve(args[0])
        if p in self.dirs:
            self.cwd = p
            return [], []
        if p in self.files:
            return [], [f"bash: cd: {args[0]}: Not a directory"]
        return [], [f"bash: cd: {args[0]}: No such file or directory"]

    def _touch(self, args):
        expanded = self._expand(args)
        if not expanded:
            return [], ["touch: missing file operand"]
        for a in expanded:
            p = self._resolve(a)
            if p in self.dirs:
                return [], [f"touch: cannot touch '{a}': Is a directory"]
            self.files.setdefault(p, "")
            self.latest = p
        return [], []

    def _cat(self, args, stdin_lines):
        if not args:
            return list(stdin_lines or []), []
        out = []
        for a in self._expand(args):
            p = self._resolve(a)
            if p in self.files:
                out.extend(self.files[p].rstrip("\n").split("\n"))
            elif p in self.dirs:
                out.append(f"cat: {a}: Is a directory")
            else:
                out.append(f"cat: {a}: No such file or directory")
        return out, []

    def _head_tail(self, cmd, args, stdin_lines):
        n = 10
        files = []
        i = 0
        while i < len(args):
            a = args[i]
            if a == "-n" and i + 1 < len(args):
                n = int(args[i + 1]); i += 2
            elif a.startswith("-n"):
                n = int(a[2:]); i += 1
            elif re.fullmatch(r"-\d+", a):
                n = int(a[1:]); i += 1
            elif a.startswith("-"):
                i += 1
            else:
                files.append(a); i += 1
        lines = self._read_lines(files, stdin_lines)
        if lines is None:
            return [], [f"{cmd}: No such file or directory"]
        return (lines[:n] if cmd == "head" else lines[-n:]), []

    def _wc(self, args, stdin_lines):
        count_lines = "-l" in args
        files = [a for a in args if not a.startswith("-")]
        lines = self._read_lines(files, stdin_lines)
        if lines is None:
            return [], ["wc: No such file or directory"]
        if count_lines:
            return [str(len(lines))], []
        words = sum(len(l.split()) for l in lines)
        chars = sum(len(l) for l in lines)
        name = (" " + files[0]) if files else ""
        return [f"  {len(lines)}  {words}  {chars}{name}"], []

    def _grep(self, args, stdin_lines):
        flags = [a for a in args if a.startswith("-") and len(a) > 1]
        pos = [a for a in args if not (a.startswith("-") and len(a) > 1)]
        if not pos:
            return [], ["grep: missing pattern"]
        pattern = pos[0]
        files = pos[1:]
        lines = self._read_lines(files, stdin_lines)
        if lines is None:
            return [], ["grep: No such file or directory"]
        rx = re.compile(re.escape(pattern), re.IGNORECASE if "-i" in flags else 0)
        show_num = "-n" in flags
        out = []
        for idx, line in enumerate(lines, 1):
            if rx.search(line):
                out.append(f"{idx}:{line}" if show_num else line)
        return out, []

    def _python(self, args):
        if not args:
            return [], ["python3: no file given"]
        p = self._resolve(args[0])
        if p not in self.files:
            return [], [f"python3: can't open file '{args[0]}': No such file or directory"]
        stdout, stderr = run_lesson_code(self.files[p])
        lines = stdout.rstrip("\n").split("\n") if stdout.rstrip("\n") else []
        elines = stderr.rstrip("\n").split("\n") if stderr.strip() else []
        return lines, elines

    def _run_executable(self, cmd):
        p = self._resolve(cmd)
        if p not in self.files:
            return [], [f"bash: {cmd}: No such file or directory"]
        if p not in self.executable:
            return [], [f"bash: {cmd}: Permission denied"]
        stdout, stderr = run_lesson_code(self.files[p])
        lines = stdout.rstrip("\n").split("\n") if stdout.rstrip("\n") else []
        elines = stderr.rstrip("\n").split("\n") if stderr.strip() else []
        return lines, elines

    def _mv(self, args):
        if len(args) != 2:
            return [], ["mv: missing file operand"]
        src, dst = self._resolve(args[0]), self._resolve(args[1])
        if src not in self.files and src not in self.dirs:
            return [], [f"mv: cannot stat '{args[0]}': No such file or directory"]
        if src in self.files:
            self.files[dst] = self.files.pop(src)
            if src in self.executable:
                self.executable.discard(src)
        else:
            base = src.rstrip("/") + "/"
            self.dirs = {d for d in self.dirs if not (d == src or d.startswith(base))}
            self.dirs.add(dst)
            remap = {}
            for f, c in self.files.items():
                if f.startswith(base):
                    remap[dst + "/" + f[len(base):]] = c
                else:
                    remap[f] = c
            self.files = remap
        self.latest = dst
        return [], []

    def _cp(self, args):
        if len(args) != 2:
            return [], ["cp: missing file operand"]
        src, dst = self._resolve(args[0]), self._resolve(args[1])
        if src not in self.files:
            return [], [f"cp: cannot stat '{args[0]}': No such file or directory"]
        self.files[dst] = self.files[src]
        self.latest = dst
        return [], []

    def _rm(self, args):
        recursive = any(a in ("-r", "-rf", "-fr") for a in args)
        targets = [a for a in args if not a.startswith("-")]
        if not targets:
            return [], ["rm: missing operand"]
        out = []
        for a in targets:
            p = self._resolve(a)
            if p in self.dirs:
                if recursive:
                    base = p.rstrip("/") + "/"
                    self.dirs = {d for d in self.dirs if not (d == p or d.startswith(base))}
                    self.files = {f: c for f, c in self.files.items() if not f.startswith(base)}
                    self.executable = {f for f in self.executable if not f.startswith(base)}
                else:
                    out.append(f"rm: cannot remove '{a}': Is a directory")
            elif p in self.files:
                del self.files[p]
                self.executable.discard(p)
            else:
                out.append(f"rm: cannot remove '{a}': No such file or directory")
        return out, []

    def _chmod(self, args):
        if not args:
            return [], ["chmod: missing operand"]
        mode = args[0]
        targets = self._expand(args[1:])
        if "+x" in mode or "u+x" in mode or "a+x" in mode:
            for t in targets:
                p = self._resolve(t)
                if p in self.files:
                    self.executable.add(p)
                    self.latest = p
            return [], []
        return [], [f"chmod: invalid mode: '{mode}'"]


# ============================================================================
# CLOUD & DEVOPS — a simulated enterprise environment (offline, deterministic)
# ============================================================================
# The learner writes real infrastructure-as-code (Dockerfiles, Ansible
# playbooks, Terraform, boto3 scripts, CI workflows) and these simulators
# EXECUTE it against an in-memory "cloud": fake AWS (S3 + EC2/VPS), a local
# docker daemon, terraform state, an ansible inventory, git, and a CI/CD
# pipeline. Nothing touches the network — everything replays deterministically
# so lessons can be tested and resumed exactly.

# ---- tiny YAML subset parser (two-space indentation) -----------------------

def _yaml_lines(text):
    """Strip comments/blank lines; return (indent, content) pairs."""
    out = []
    for raw in text.splitlines():
        line = raw.rstrip()
        if not line.strip() or line.lstrip().startswith("#"):
            continue
        indent = len(line) - len(line.lstrip(" "))
        content = line.strip()
        # strip a trailing `# comment` (outside quotes) — naive but fits the subset
        i = content.find("#")
        if i > 0 and content[i - 1] == " ":
            content = content[:i].rstrip()
        if not content:
            continue
        out.append((indent, content))
    return out


def _yaml_scalar(s):
    s = s.strip()
    if s in ("", "null", "~", "None"):
        return None
    if s.lower() in ("yes", "true", "on"):
        return True
    if s.lower() in ("no", "false", "off"):
        return False
    if len(s) >= 2 and s[0] == s[-1] and s[0] in ("'", '"'):
        return s[1:-1]
    if s.startswith("[") and s.endswith("]"):
        inner = s[1:-1].strip()
        if not inner:
            return []
        return [x.strip().strip("'\"") for x in inner.split(",")]
    if re.fullmatch(r"-?\d+", s):
        return int(s)
    return s


def yaml_parse(text):
    """Parse the tiny YAML subset we teach into Python lists/dicts."""
    lines = _yaml_lines(text)
    if not lines:
        return None
    root_is_list = lines[0][1].startswith("- ")
    root = [] if root_is_list else {}
    stack = [(-1, root, None)]  # (indent, container, key)

    def down_to(indent):
        while stack and stack[-1][0] >= indent:
            stack.pop()

    i, n = 0, len(lines)
    while i < n:
        indent, content = lines[i]
        if content.startswith("- "):
            down_to(indent)
            parent = stack[-1][1]
            if not isinstance(parent, list):
                parent = root
            rest = content[2:].strip()
            if ":" in rest and rest.split(":", 1)[0].strip():
                k, _, v = rest.partition(":")
                item = {k.strip(): _yaml_scalar(v) if v.strip() else None}
                parent.append(item)
                stack.append((indent, item, None))
            else:
                parent.append(_yaml_scalar(rest))
            i += 1
            continue
        if ":" in content:
            k, _, v = content.partition(":")
            k = k.strip()
            down_to(indent)
            parent = stack[-1][1]
            if not isinstance(parent, dict):
                parent = root
            if v.strip():
                parent[k] = _yaml_scalar(v)
            else:
                nxt = i + 1
                if nxt < n and lines[nxt][0] > indent:
                    child = [] if lines[nxt][1].startswith("- ") else {}
                    parent[k] = child
                    stack.append((indent, child, None))
                else:
                    parent[k] = None
            i += 1
            continue
        i += 1
    return root


def ini_parse(text):
    """Parse a tiny INI inventory (`[group]` then one host per line)."""
    groups = {}
    cur = None
    for raw in text.splitlines():
        s = raw.strip()
        if not s or s.startswith("#") or s.startswith(";"):
            continue
        if s.startswith("[") and s.endswith("]"):
            cur = s[1:-1]
            groups.setdefault(cur, [])
        elif cur is not None:
            groups[cur].append(s)
    return groups


def _hcl_val(v):
    v = v.strip()
    if len(v) >= 2 and v[0] == '"' and v[-1] == '"':
        return v[1:-1]
    if v.lower() in ("true", "false"):
        return v.lower() == "true"
    if re.fullmatch(r"\d+", v):
        return int(v)
    if v.startswith("[") and v.endswith("]"):
        return [x.strip().strip('"') for x in v[1:-1].split(",") if x.strip()]
    return v


def hcl_parse(text):
    """Parse the tiny HCL subset (blocks + `key = value` attrs)."""
    blocks, stack = [], []
    for raw in text.splitlines():
        s = raw.strip()
        if not s or s.startswith("#") or s.startswith("//"):
            continue
        if s.endswith("{") and "=" not in s:
            header = s[:-1].strip()
            parts = header.split()
            block = {"type": parts[0], "labels": [p.strip('"') for p in parts[1:]],
                     "attrs": {}, "blocks": []}
            if stack:
                stack[-1]["blocks"].append(block)
            else:
                blocks.append(block)
            stack.append(block)
        elif s == "}":
            if stack:
                stack.pop()
        elif "=" in s and stack:
            k, _, v = s.partition("=")
            stack[-1]["attrs"][k.strip()] = _hcl_val(v)
    return blocks


# ---- git (simulated) --------------------------------------------------------

class GitRepo:
    def __init__(self, fs):
        self.fs = fs
        self.inited = False
        self.branch = "main"
        self.commits = []              # list of {hash, msg, branch}
        self.staged = {}               # path -> content snapshot at `git add`
        self.committed = {}            # path -> content snapshot at last commit
        self.n = 0

    def _hash(self, msg):
        self.n += 1
        return "a%06d" % self.n

    def _status_lines(self):
        out = []
        if not self.inited:
            return ["fatal: not a git repository (or any of the parent directories)"]
        if self.branch:
            out.append(f"On branch {self.branch}")
        changed = [p for p, c in self.fs.files.items() if self.committed.get(p) != c]
        # untracked = in fs but never committed
        untracked = [p for p in self.fs.files if p not in self.committed]
        staged_names = sorted(self.staged.keys())
        if staged_names:
            out.append("Changes to be committed:")
            for p in staged_names:
                out.append(f"  new file:   {p}")
        if changed:
            out.append("Changes not staged for commit:")
            for p in sorted(changed):
                out.append(f"  modified:   {p}")
        if untracked:
            out.append("Untracked files:")
            for p in sorted(untracked):
                out.append(f"\t{p}")
        if not staged_names and not changed and not untracked:
            out.append("nothing to commit, working tree clean")
        return out

    def run(self, rest):
        parts = rest.split()
        if not parts:
            return [], ["usage: git <command>"]
        cmd = parts[0]
        args = parts[1:]
        if cmd == "init":
            self.inited = True
            return [f"Initialized empty Git repository"], []
        if not self.inited:
            return [], ["fatal: not a git repository"]
        if cmd == "add":
            if not args:
                return [], ["Nothing specified, nothing added."]
            added = []
            for a in args:
                if a == "." or a == "-A":
                    for p, c in self.fs.files.items():
                        self.staged[p] = c
                        added.append(p)
                else:
                    p = self.fs._resolve(a)
                    if p in self.fs.files:
                        self.staged[p] = self.fs.files[p]
                        added.append(p)
                    else:
                        return [], [f"fatal: pathspec '{a}' did not match any files"]
            return (["staged: " + ", ".join(added)] if added else []), []
        if cmd == "commit":
            msg = ""
            m = re.search(r'-m\s+["\']([^"\']*)["\']', rest)
            if m:
                msg = m.group(1)
            else:
                m = re.search(r'-m\s+(\S+)', rest)
                if m:
                    msg = m.group(1)
            if not self.staged:
                return [], ["nothing to commit, working tree clean"]
            h = self._hash(msg)
            self.committed.update(self.staged)
            self.commits.append({"hash": h, "msg": msg, "branch": self.branch})
            self.staged = {}
            out = [f"[{self.branch} {h}] {msg}", f" {len(self.commits)} file changed" if len(self.commits) == 1 else f" {len(self.commits)} files changed"]
            # trigger the CI/CD pipeline on every commit (teaches the loop)
            return out, []
        if cmd == "log":
            if not self.commits:
                return [], []
            out = []
            for c in reversed(self.commits):
                out.append(f"commit {c['hash']} ({c['branch']})")
                if c["msg"]:
                    out.append(f"    {c['msg']}")
            return out, []
        if cmd == "status":
            return self._status_lines(), []
        if cmd == "branch":
            if args and not args[0].startswith("-"):
                return [f"branch '{args[0]}' created"], []
            return [f"* {self.branch}"], []
        if cmd in ("checkout", "switch"):
            if args and args[0] == "-b":
                self.branch = args[1] if len(args) > 1 else "feature"
            elif args:
                self.branch = args[0]
            return [f"Switched to branch '{self.branch}'"], []
        if cmd == "merge":
            if args:
                return [f"Merge made by the 'recursive' strategy"], []
            return [], ["fatal: no branch specified"]
        if cmd == "diff":
            changed = [p for p, c in self.fs.files.items() if self.committed.get(p) != c]
            if not changed:
                return [], []
            return ["diff --git a/" + p for p in sorted(changed)], []
        return [], [f"git: '{cmd}' is not a git command"]


# ---- docker (simulated) ------------------------------------------------------

class K8sEnv:
    """A tiny offline Kubernetes: deployments, pods, services, rollouts.
    `run(rest)` behaves like kubectl — desired state, self-healing, rolling
    updates — so the lessons read like a real cluster."""

    def __init__(self, fs):
        self.fs = fs
        self.deployments = {}   # name -> {image, replicas, ready, rev}
        self.pods = {}          # name -> {owner|None, image, status, restarts}
        self.services = {}      # name -> {type, port}
        self.healed = 0         # pods the controller replaced after deletion
        self.next = 1

    def _sync(self, name):
        """Realize the desired state: pods match the deployment's replicas.
        This is the 'self-healing' magic — delete a pod, it comes back."""
        d = self.deployments[name]
        d["ready"] = d["replicas"]
        self.pods = {k: v for k, v in self.pods.items()
                     if v.get("owner") != name}
        for i in range(d["replicas"]):
            pn = f"{name}-{i:02d}"
            self.pods[pn] = {"owner": name, "image": d["image"],
                             "status": "Running", "restarts": 0}

    def run(self, rest):
        parts = rest.split()
        if not parts:
            return [], ["kubectl: missing command"]
        cmd = parts[0]
        if cmd == "get":
            return self._get(parts[1:])
        if cmd == "create" and parts[1:2] == ["deployment"]:
            name = parts[2]
            img = "nginx"
            if "--image" in parts:
                img = parts[parts.index("--image") + 1].split("=")[-1]
            self.deployments[name] = {"image": img, "replicas": 1,
                                      "ready": 1, "rev": 1}
            self._sync(name)
            return [f"deployment.apps/{name} created"], []
        if cmd == "run":
            name = parts[1]
            img = "nginx"
            if "--image" in parts:
                img = parts[parts.index("--image") + 1].split("=")[-1]
            self.pods[name] = {"owner": None, "image": img,
                               "status": "Running", "restarts": 0}
            return [f"pod/{name} created"], []
        if cmd == "scale":
            # kubectl scale deployment web --replicas=3
            # kubectl scale deployment/web --replicas=3
            if "/" in parts[1]:
                name = parts[1].split("/")[-1]
            elif parts[1].startswith("deploy"):
                name = parts[2] if len(parts) > 2 else ""
            else:
                name = parts[1].split("/")[-1]
            if name not in self.deployments:
                return [], [f'Error from server (NotFound): deployments.apps '
                            f'"{name}" not found']
            replicas = int(parts[parts.index("--replicas") + 1].split("=")[-1]) \
                if "--replicas" in parts else \
                int(next((p for p in parts if p.startswith("--replicas=")),
                         "--replicas=1").split("=")[-1])
            self.deployments[name]["replicas"] = replicas
            self._sync(name)
            return [f"deployment.apps/{name} scaled"], []
        if cmd == "expose":
            # kubectl expose deployment web --port=80 --type=LoadBalancer
            if "/" in parts[1]:
                name = parts[1].split("/")[-1]
            elif parts[1].startswith("deploy"):
                name = parts[2] if len(parts) > 2 else ""
            else:
                name = parts[1].split("/")[-1]
            port = "80"
            if "--port" in parts:
                port = parts[parts.index("--port") + 1].split("=")[-1]
            elif any(p.startswith("--port=") for p in parts):
                port = next(p for p in parts if p.startswith("--port=")).split("=")[-1]
            stype = "ClusterIP"
            if "--type" in parts:
                stype = parts[parts.index("--type") + 1].split("=")[-1]
            elif any(p.startswith("--type=") for p in parts):
                stype = next(p for p in parts if p.startswith("--type=")).split("=")[-1]
            self.services[name] = {"type": stype, "port": port}
            return [f"service/{name} exposed"], []
        if cmd == "set":
            # kubectl set image deployment web app=img:v2
            # kubectl set image deployment/web app=img:v2
            if "deployment" in parts:
                di = parts.index("deployment")
                if "/" in parts[di]:
                    name = parts[di].split("/")[-1]
                else:
                    name = parts[di + 1] if di + 1 < len(parts) else ""
            else:
                name = parts[2].split("/")[-1]
            img = parts[-1].split("=")[-1]
            d = self.deployments.get(name)
            if not d:
                return [], [f'Error from server (NotFound): deployments.apps '
                            f'"{name}" not found']
            d["image"] = img
            d["rev"] += 1
            self._sync(name)
            return [f"deployment.apps/{name} image updated"], []
        if cmd == "rollout":
            return self._rollout(parts[1:])
        if cmd == "describe":
            return self._describe(parts[1:])
        if cmd == "logs":
            return self._logs(parts[1:])
        if cmd == "delete":
            return self._delete(parts[1:])
        if cmd == "apply":
            return self._apply(parts[1:])
        return [], [f"kubectl: '{cmd}' is not supported in this lab"]

    def _get(self, args):
        kind = args[0] if args else "pods"
        if kind == "nodes":
            return ["NAME        STATUS   ROLES           AGE   VERSION",
                    "minikube    Ready    control-plane   3d    v1.31.0"], []
        if kind == "pods":
            if not self.pods:
                return ["No resources found in default namespace."], []
            out = ["NAME                    READY   STATUS    RESTARTS   AGE"]
            for pn in sorted(self.pods):
                p = self.pods[pn]
                out.append(f"{pn:<24} 1/1     {p['status']:<9} "
                           f"{p['restarts']}          12m")
            return out, []
        if kind in ("deployments", "deploy"):
            if not self.deployments:
                return ["No resources found in default namespace."], []
            out = ["NAME   READY   UP-TO-DATE   AVAILABLE   AGE"]
            for n in sorted(self.deployments):
                d = self.deployments[n]
                out.append(f"{n:<7} {d['ready']}/{d['replicas']}     "
                           f"{d['replicas']}            {d['ready']}          "
                           f"13m")
            return out, []
        if kind in ("services", "svc"):
            if not self.services:
                return ["No resources found in default namespace."], []
            out = ["NAME   TYPE           CLUSTER-IP   EXTERNAL-IP   "
                   "PORT(S)   AGE"]
            for n in sorted(self.services):
                s = self.services[n]
                ext = "<pending>" if s["type"] == "LoadBalancer" else "<none>"
                out.append(f"{n:<7} {s['type']:<15} 10.96.0.1    {ext:<13} "
                           f"{s['port']}/TCP   10m")
            return out, []
        return [], [f'error: the server doesn\'t have a resource type '
                    f'"{kind}"']

    def _rollout(self, args):
        if not args:
            return [], ["kubectl rollout: use status | undo | history"]
        kind = args[0]
        # kubectl rollout status deployment web
        # kubectl rollout status deployment/web
        if len(args) > 1 and "/" in args[1]:
            name = args[1].split("/")[-1]
        else:
            name = args[2] if len(args) > 2 else ""
        d = self.deployments.get(name)
        if not d:
            return [], [f'Error from server (NotFound): deployments.apps '
                        f'"{name}" not found']
        if kind == "status":
            return [f'Waiting for deployment "{name}" rollout to finish: '
                    f'{d["replicas"]} out of {d["replicas"]} new replicas '
                    f'have been updated...',
                    f'deployment "{name}" successfully rolled out'], []
        if kind == "undo":
            d["rev"] = max(1, d["rev"] - 1)
            d["ready"] = d["replicas"]
            return [f"deployment.apps/{name} rolled back"], []
        if kind == "history":
            out = [f"deployment.apps/{name}", "REVISION  CHANGE-CAUSE"]
            for r in range(d["rev"], 0, -1):
                out.append(f"{r}         <none>")
            return out, []
        return [], ["kubectl rollout: use status | undo | history"]

    def _describe(self, args):
        if len(args) < 2:
            return [], ["kubectl describe: provide deployment/NAME"]
        name = args[1].split("/")[-1]
        d = self.deployments.get(name)
        if not d:
            return [], [f'Error from server (NotFound): deployments.apps '
                        f'"{name}" not found']
        return [f"Name:                   {name}",
                "Namespace:              default",
                f"Replicas:               {d['replicas']} desired | "
                f"{d['ready']} updated | {d['ready']} available",
                f"Image:                  {d['image']}",
                f"Revision:               {d['rev']}",
                "Conditions:",
                "  Type           Status  Reason",
                "  ----           ------  ------",
                "  Available      True    MinimumReplicasAvailable"], []

    def _logs(self, args):
        name = args[0].split("/")[-1] if args else ""
        d = self.deployments.get(name)
        img = d["image"] if d else "app:latest"
        if "v2" in img:
            return ["[2026-09-09 18:00:01] serving v2 — new feature live",
                    "[2026-09-09 18:00:02] GET / 200 12ms",
                    "[2026-09-09 18:00:03] GET /health 200 2ms"], []
        return ["[2026-09-09 17:59:58] serving v1",
                "[2026-09-09 17:59:59] GET / 200 15ms",
                "[2026-09-09 18:00:00] GET /health 200 2ms"], []

    def _delete(self, args):
        if len(args) < 2:
            return [], ["kubectl delete: provide TYPE NAME"]
        kind = args[0]
        name = args[1].split("/")[-1]
        if kind.startswith("deploy"):
            if name in self.deployments:
                del self.deployments[name]
                self.pods = {k: v for k, v in self.pods.items()
                             if v.get("owner") != name}
                return [f'deployment.apps "{name}" deleted'], []
        elif kind.startswith("service"):
            if name in self.services:
                del self.services[name]
                return [f'service "{name}" deleted'], []
        elif kind.startswith("pod"):
            if name in self.pods:
                owner = self.pods[name].get("owner")
                del self.pods[name]
                if owner:
                    self.healed += 1    # the control loop replaces it
                    self._sync(owner)   # self-healing: the replica returns
                return [f'pod "{name}" deleted'], []
        return [], [f'Error from server (NotFound): {kind} "{name}" not found']

    def _apply(self, args):
        fname = None
        if "-f" in args:
            fname = args[args.index("-f") + 1]
        if not fname:
            return [], ["kubectl apply: provide -f FILE"]
        p = self.fs._resolve(fname)
        content = self.fs.files.get(p)
        if not content:
            return [], [f'error: the path "{fname}" does not exist']
        kind = re.search(r"^kind:\s*(\w+)", content, re.M)
        name = re.search(r"^\s{2}name:\s*(\S+)", content, re.M)
        if not kind or not name:
            return [], ["error: unable to parse the manifest"]
        kind, name = kind.group(1), name.group(1)
        if kind == "Deployment":
            img = re.search(r"image:\s*(\S+)", content)
            reps = re.search(r"replicas:\s*(\d+)", content)
            self.deployments[name] = {
                "image": img.group(1) if img else "nginx",
                "replicas": int(reps.group(1)) if reps else 1,
                "ready": int(reps.group(1)) if reps else 1, "rev": 1}
            self._sync(name)
            return [f"deployment.apps/{name} created"], []
        if kind == "Service":
            port = re.search(r"port:\s*(\d+)", content)
            stype = re.search(r"type:\s*(\w+)", content)
            self.services[name] = {"type": stype.group(1) if stype
                                   else "ClusterIP",
                                   "port": port.group(1) if port else "80"}
            return [f"service/{name} created"], []
        return [], [f'error: unsupported kind "{kind}" in this lab']


class DockerEnv:
    def __init__(self, fs):
        self.fs = fs
        self.images = {}       # name -> {"id": str, "exposed": [ports]}
        self.containers = {}   # name -> {"image", "running", "ports"}
        self.next = 1

    def _dockerfile(self):
        p = self.fs._resolve("Dockerfile")
        return self.fs.files.get(p, "")

    def run(self, rest):
        parts = rest.split()
        if not parts:
            return [], ["docker: missing command"]
        cmd = parts[0]
        if cmd == "build":
            tag = None
            if "-t" in parts:
                ti = parts.index("-t")
                if ti + 1 < len(parts):
                    tag = parts[ti + 1]
            tag = tag or "app:latest"
            df = self._dockerfile()
            if not df:
                return [], ["unable to prepare context: unable to evaluate symlinks in Dockerfile path: lstat Dockerfile: no such file or directory"]
            lines = []
            for ln in df.splitlines():
                s = ln.strip()
                if s.upper().startswith("FROM "):
                    lines.append(f" ---> pulling {s[5:].strip()}")
            lines.append(" ---> build complete")
            self.images[tag] = {"id": "img%03d" % self.next, "exposed": []}
            self.next += 1
            return ["Sending build context to Docker daemon",
                    "Step 1/1 : FROM python:3.11-slim"] + lines + [f"Successfully tagged {tag}"], []
        if cmd == "images":
            if not self.images:
                return ["REPOSITORY  TAG  IMAGE ID  CREATED  SIZE"], []
            out = ["REPOSITORY  TAG  IMAGE ID  CREATED  SIZE"]
            for name, im in self.images.items():
                repo, _, tag = name.partition(":")
                out.append(f"{repo}  {tag or 'latest'}  {im['id']}  2 minutes ago  128MB")
            return out, []
        if cmd == "run":
            name, img = None, None
            ports = []
            detached = "-d" in parts
            if "--name" in parts:
                ni = parts.index("--name")
                if ni + 1 < len(parts):
                    name = parts[ni + 1]
            if "-p" in parts:
                pi = parts.index("-p")
                if pi + 1 < len(parts):
                    ports.append(parts[pi + 1])
            # last positional arg = image
            for a in parts:
                if not a.startswith("-") and a not in ("run", name, *ports):
                    img = a
            if not img:
                return [], ["docker run requires an image"]
            if img not in self.images:
                return [], [f"Unable to find image '{img}' locally: docker: Error response from daemon: pull access denied"]
            name = name or f"container{self.next}"
            cid = "c%03d" % self.next
            self.next += 1
            self.containers[name] = {"image": img, "running": True, "ports": ports, "id": cid}
            out = [cid]
            if not detached:
                # foreground run shows app output (first lines of the image's CMD)
                out += self._fake_logs(img)
            return out, []
        if cmd == "ps":
            if not self.containers:
                return ["CONTAINER ID  IMAGE  STATUS  PORTS  NAMES"], []
            out = ["CONTAINER ID  IMAGE  STATUS  PORTS  NAMES"]
            for name, c in self.containers.items():
                st = "Up 2 minutes" if c["running"] else "Exited (0)"
                out.append(f"{c['id']}  {c['image']}  {st}  {' '.join(c['ports'])}  {name}")
            return out, []
        if cmd == "stop":
            args = parts[1:]
            if not args:
                return [], ["docker stop requires a container name"]
            out, errs = [], []
            for n in args:
                if n in self.containers:
                    self.containers[n]["running"] = False
                    out.append(n)
                else:
                    errs.append(f"Error: No such container: {n}")
            return out, errs
        if cmd == "start":
            for n in parts[1:]:
                if n in self.containers:
                    self.containers[n]["running"] = True
            return parts[1:], []
        if cmd == "rm":
            args = parts[1:]
            if not args:
                return [], ["docker rm requires a container name"]
            out, errs = [], []
            for n in args:
                if n not in self.containers:
                    errs.append(f"Error: No such container: {n}")
                elif self.containers[n]["running"]:
                    errs.append(f"Error response from daemon: You cannot remove "
                                f"a running container {n}. Stop the container "
                                f"before attempting removal")
                else:
                    del self.containers[n]
                    out.append(n)
            return out, errs
        if cmd == "rmi":
            for n in parts[1:]:
                self.images.pop(n, None)
            return [], []
        if cmd == "logs":
            n = parts[1] if len(parts) > 1 else ""
            if n in self.containers:
                return self._fake_logs(self.containers[n]["image"]), []
            return [], [f"Error: No such container: {n}"]
        if cmd == "exec":
            # docker exec <name> <cmd...>
            n = parts[1] if len(parts) > 1 else ""
            if n in self.containers:
                return [f"(inside {n}) ran: {' '.join(parts[2:])}"], []
            return [], [f"Error: No such container: {n}"]
        return [], [f"docker: unknown command '{cmd}'"]

    def _fake_logs(self, img):
        return [" * Serving Flask app", " * Running on http://0.0.0.0:5000"]


# ---- AWS (simulated S3 + EC2/VPS) -------------------------------------------

class AwsEnv:
    def __init__(self, fs):
        self.fs = fs
        self.buckets = {}      # name -> {key: content}
        self.instances = {}    # id -> {"ImageId","InstanceType","State":{...}}
        self.next_inst = 1
        self.lambda_fns = {}      # name -> {"code","runtime","handler"}
        self.dynamo_tables = {}   # name -> list of native item dicts
        self.iam_users = set()    # usernames
        self.iam_roles = {}       # role -> {"policies": []}
        self.iam_policies = {}    # policy name -> arn

    def run(self, rest):
        try:
            parts = shlex.split(rest)
        except ValueError:
            parts = rest.split()
        if not parts:
            return [], ["usage: aws <service> <command>"]
        svc = parts[0]
        if svc == "s3":
            return self._s3(parts[1:])
        if svc == "ec2":
            return self._ec2(parts[1:])
        if svc == "lambda":
            return self._lambda(parts[1:])
        if svc == "dynamodb":
            return self._dynamodb(parts[1:])
        if svc == "iam":
            return self._iam(parts[1:])
        if svc in ("--version", "version"):
            return ["aws-cli/2.15.0"], []
        return [], [f"aws: error: argument command: Invalid choice, valid choices: s3 | ec2 | lambda | dynamodb | iam"]

    def _s3(self, args):
        if not args:
            return [], ["usage: aws s3 <command>"]
        cmd = args[0]
        if cmd == "mb":
            if len(args) < 2:
                return [], ["usage: aws s3 mb <s3://bucket>"]
            name = args[1].replace("s3://", "")
            if name in self.buckets:
                return [], [f"make_bucket failed: s3://{name} An error occurred (BucketAlreadyOwnedByYou)"]
            self.buckets[name] = {}
            return [f"make_bucket: {name}"], []
        if cmd == "ls":
            if len(args) == 1:
                if not self.buckets:
                    return [], []
                return [f"2026-09-07 09:00:00 {name}" for name in sorted(self.buckets)], []
            name = args[1].replace("s3://", "")
            if name not in self.buckets:
                return [], [f"An error occurred (NoSuchBucket): {name}"]
            return [f"2026-09-07 09:00:00 {len(c):>5} {k}" for k, c in sorted(self.buckets[name].items())], []
        if cmd == "cp":
            src, dst = args[1], args[2]
            if src.startswith("s3://"):
                # download
                b, _, k = src[5:].partition("/")
                if b in self.buckets and k in self.buckets[b]:
                    self.fs.files[self.fs._resolve(dst)] = self.buckets[b][k]
                    return [f"download: s3://{b}/{k} to ./{dst}"], []
                return [], [f"fatal error: An error occurred (404) when calling the HeadObject operation"]
            # upload
            b, _, k = dst[5:].partition("/")
            p = self.fs._resolve(src)
            if b not in self.buckets:
                return [], [f"upload failed: {dst} An error occurred (NoSuchBucket)"]
            body = self.fs.files.get(p, src)
            self.buckets[b][k] = body
            return [f"upload: ./{src} to {dst}"], []
        if cmd == "rm":
            if len(args) < 2:
                return [], ["usage: aws s3 rm <s3://bucket/key>"]
            b, _, k = args[1][5:].partition("/")
            if b in self.buckets:
                self.buckets[b].pop(k, None)
            return [f"delete: s3://{b}/{k}"], []
        if cmd == "rb":
            b = args[1].replace("s3://", "")
            if b in self.buckets and self.buckets[b]:
                return [], [f"remove_bucket failed: s3://{b} An error occurred (BucketNotEmpty)"]
            self.buckets.pop(b, None)
            return [f"remove_bucket: {b}"], []
        return [], [f"aws s3: unknown command '{cmd}'"]

    def _ec2(self, args):
        if not args:
            return [], ["usage: aws ec2 <command>"]
        cmd = args[0]
        if cmd == "run-instances":
            d = dict(zip(args[1::2], args[2::2]))
            ami = d.get("--image-id", "ami-default")
            itype = d.get("--instance-type", "t3.micro")
            iid = "i-%04d" % self.next_inst
            self.next_inst += 1
            self.instances[iid] = {"ImageId": ami, "InstanceType": itype,
                                   "State": {"Name": "running"}}
            return [f"INSTANCE  {iid}  {ami}  {itype}  running"], []
        if cmd == "describe-instances":
            if not self.instances:
                return ["Reservations: []"], []
            out = []
            for iid, inst in self.instances.items():
                out.append(f"{iid}  {inst['ImageId']}  {inst['InstanceType']}  {inst['State']['Name']}")
            return out, []
        if cmd in ("terminate-instances", "stop-instances", "start-instances"):
            state = {"terminate-instances": "terminated",
                     "stop-instances": "stopped",
                     "start-instances": "running"}[cmd]
            ids = []
            if "--instance-ids" in args:
                ids = args[args.index("--instance-ids") + 1:]
            for iid in ids:
                if iid in self.instances:
                    self.instances[iid]["State"]["Name"] = state
            return [f"{iid}: {state}" for iid in ids], []
        return [], [f"aws ec2: unknown command '{cmd}'"]

    def _lambda(self, args):
        if not args:
            return [], ["usage: aws lambda <command>"]
        cmd = args[0]
        if cmd == "create-function":
            d = _aws_flags(args[1:])
            name = d.get("function-name", "fn")
            handler = d.get("handler", "lambda_function.handler")
            runtime = d.get("runtime", "python3.11")
            code = ""
            zf = d.get("zip-file", "")
            if zf.startswith("fileb://"):
                p = self.fs._resolve(zf[8:])
                code = self.fs.files.get(p, "")
            self.lambda_fns[name] = {"code": code, "runtime": runtime, "handler": handler}
            return [f"FunctionName: {name}", f"Runtime: {runtime}", f"Handler: {handler}",
                    f"FunctionArn: arn:aws:lambda:us-east-1:123456789012:function:{name}"], []
        if cmd == "invoke":
            d = _aws_flags(args[1:])
            name = d.get("function-name", "")
            if name not in self.lambda_fns:
                return [], [f"An error occurred (ResourceNotFoundException): Function not found: {name}"]
            fn = self.lambda_fns[name]
            func = fn["handler"].split(".")[-1]
            code = fn["code"] + f"\nprint({func}({{}}, None))\n"
            stdout, stderr = run_lesson_code(code)
            out = ["Status: 200", "Execution result:"]
            if stderr.strip():
                out += ["(error)"] + stderr.strip().splitlines()
            else:
                out += stdout.rstrip("\n").split("\n") if stdout.rstrip("\n") else ["(no output)"]
            return out, []
        if cmd == "list-functions":
            if not self.lambda_fns:
                return ["Functions: []"], []
            return [f"{n}" for n in sorted(self.lambda_fns)], []
        return [], [f"aws lambda: unknown command '{cmd}'"]

    def _dynamodb(self, args):
        if not args:
            return [], ["usage: aws dynamodb <command>"]
        cmd = args[0]
        if cmd == "create-table":
            d = _aws_flags(args[1:])
            name = d.get("table-name", "")
            self.dynamo_tables.setdefault(name, [])
            return [f"TableDescription: TableName {name} · status ACTIVE"], []
        if cmd == "put-item":
            d = _aws_flags(args[1:])
            name = d.get("table-name", "")
            try:
                item = _ddb_from_json(json.loads(d.get("item", "{}")))
            except Exception:
                return [], ["An error occurred (ValidationException): invalid item JSON"]
            if name not in self.dynamo_tables:
                return [], [f"An error occurred (ResourceNotFoundException): Table not found: {name}"]
            self.dynamo_tables[name].append(item)
            return [], []
        if cmd == "get-item":
            d = _aws_flags(args[1:])
            name = d.get("table-name", "")
            key = _ddb_from_json(json.loads(d.get("key", "{}")))
            for it in self.dynamo_tables.get(name, []):
                if all(it.get(k) == v for k, v in key.items()):
                    return [json.dumps(_ddb_to_json(it))], []
            return ["{}"], []
        if cmd == "scan":
            d = _aws_flags(args[1:])
            name = d.get("table-name", "")
            items = self.dynamo_tables.get(name, [])
            if not items:
                return ["Items: []  Count: 0"], []
            return [json.dumps(_ddb_to_json(it)) for it in items] + [f"Count: {len(items)}"], []
        if cmd == "list-tables":
            return ["TableNames:"] + sorted(self.dynamo_tables), []
        return [], [f"aws dynamodb: unknown command '{cmd}'"]

    def _iam(self, args):
        if not args:
            return [], ["usage: aws iam <command>"]
        cmd = args[0]
        if cmd == "create-user":
            d = _aws_flags(args[1:])
            u = d.get("user-name", "")
            self.iam_users.add(u)
            return [f"User created: {u}"], []
        if cmd == "create-role":
            d = _aws_flags(args[1:])
            r = d.get("role-name", "")
            self.iam_roles[r] = {"policies": []}
            return [f"Role created: {r}"], []
        if cmd == "create-policy":
            d = _aws_flags(args[1:])
            p = d.get("policy-name", "")
            arn = f"arn:aws:iam::123456789012:policy/{p}"
            self.iam_policies[p] = arn
            return [f"Policy created: {arn}"], []
        if cmd == "attach-role-policy":
            d = _aws_flags(args[1:])
            r, arn = d.get("role-name", ""), d.get("policy-arn", "")
            if r in self.iam_roles:
                self.iam_roles[r]["policies"].append(arn)
            return [], []
        if cmd == "list-users":
            return [f"{u}" for u in sorted(self.iam_users)], []
        if cmd == "list-roles":
            return [f"{r} (policies: {len(self.iam_roles[r]['policies'])})" for r in sorted(self.iam_roles)], []
        return [], [f"aws iam: unknown command '{cmd}'"]


def _aws_flags(args):
    """Parse `--key value --key2 value2 ...` into a dict (bare args dropped)."""
    d = {}
    i = 0
    while i < len(args):
        a = args[i]
        if a.startswith("--") and i + 1 < len(args):
            d[a[2:]] = args[i + 1]
            i += 2
        else:
            i += 1
    return d


def _ddb_from_json(item):
    """DynamoDB low-level JSON ({\"S\": v}) → native Python dict."""
    out = {}
    for k, v in item.items():
        if isinstance(v, dict):
            if "S" in v:
                out[k] = v["S"]
            elif "N" in v:
                out[k] = int(v["N"]) if str(v["N"]).lstrip("-").isdigit() else v["N"]
            elif "BOOL" in v:
                out[k] = v["BOOL"]
            else:
                out[k] = v
        else:
            out[k] = v
    return out


def _ddb_to_json(item):
    """Native Python dict → DynamoDB low-level JSON."""
    out = {}
    for k, v in item.items():
        if isinstance(v, bool):
            out[k] = {"BOOL": v}
        elif isinstance(v, int):
            out[k] = {"N": str(v)}
        else:
            out[k] = {"S": str(v)}
    return out


# ---- terraform (simulated) ---------------------------------------------------

class TerraformEnv:
    def __init__(self, fs):
        self.fs = fs
        self.resources = {}   # "type.name" -> {"attrs": {...}}
        self.plan = []        # ("+"|"~"|"-", key, attrs)
        self.inited = False

    def _config(self):
        cfg = {}
        for path, content in self.fs.files.items():
            if path.endswith(".tf"):
                for b in hcl_parse(content):
                    if b["type"] in ("resource", "data") and b["labels"]:
                        key = ".".join(b["labels"])
                        cfg[key] = {"type": b["type"], "attrs": dict(b["attrs"])}
        return cfg

    def run(self, rest):
        parts = rest.split()
        if not parts:
            return [], ["Usage: terraform <command>"]
        cmd = parts[0]
        if cmd == "init":
            self.inited = True
            return ["Initializing the backend...",
                    "Initializing provider plugins...",
                    "Terraform has been successfully initialized!"], []
        if cmd == "plan":
            if not self.inited:
                return [], ["Error: Backend initialization required"]
            cfg = self._config()
            plan = []
            for key, r in cfg.items():
                if key not in self.resources:
                    plan.append(("+", key, r["attrs"]))
                elif self.resources[key]["attrs"] != r["attrs"]:
                    plan.append(("~", key, r["attrs"]))
            for key in list(self.resources):
                if key not in cfg:
                    plan.append(("-", key, {}))
            self.plan = plan
            if not plan:
                return ["No changes. Your infrastructure matches the configuration."], []
            out = ["Terraform will perform the following actions:"]
            for op, key, attrs in plan:
                detail = " " + ", ".join(f"{k}={v!r}" for k, v in attrs.items()) if attrs else ""
                out.append(f"  {op} {key}{detail}")
            a = sum(1 for o, _, _ in plan if o == "+")
            c = sum(1 for o, _, _ in plan if o == "~")
            d = sum(1 for o, _, _ in plan if o == "-")
            out.append(f"Plan: {a} to add, {c} to change, {d} to destroy.")
            return out, []
        if cmd == "apply":
            for op, key, attrs in self.plan:
                if op == "-":
                    self.resources.pop(key, None)
                else:
                    self.resources[key] = {"attrs": attrs}
            n = len(self.plan)
            self.plan = []
            return [f"Apply complete! Resources: {n} added/changed."], []
        if cmd == "destroy":
            self.resources.clear()
            return ["Destroy complete! Resources: 0 remaining."], []
        if cmd == "state":
            if len(parts) > 1 and parts[1] == "list":
                return sorted(self.resources.keys()), []
            return [], []
        if cmd == "show":
            return [f"{k}: {json.dumps(self.resources[k]['attrs'])}" for k in sorted(self.resources)], []
        return [], [f"terraform: unknown command '{cmd}'"]


# ---- ansible (simulated) -----------------------------------------------------

class AnsibleEnv:
    def __init__(self, fs):
        self.fs = fs
        self.hosts = {}        # host -> {"packages": set, "services": {}, "files": {}}
        self.handlers_fired = []

    def _host_state(self, host):
        return self.hosts.setdefault(host, {"packages": set(), "services": {}, "files": {}})

    def _module(self, host, module, params):
        st = self._host_state(host)
        if module == "apt":
            name = params.get("name", "")
            if name in st["packages"]:
                return False, f"{name} is already installed"
            st["packages"].add(name)
            return True, f"installed {name}"
        if module == "service":
            name = params.get("name", "")
            state = params.get("state", "started")
            if st["services"].get(name) == state:
                return False, f"{name} is already {state}"
            st["services"][name] = state
            return True, f"{name} is now {state}"
        if module == "copy":
            dest = params.get("dest", params.get("path", ""))
            content = params.get("content", self.fs.files.get(self.fs._resolve(params.get("src", "")), ""))
            if st["files"].get(dest) == content:
                return False, f"{dest} is unchanged"
            st["files"][dest] = content
            return True, f"copied to {dest}"
        if module in ("file", "template", "user", "shell", "command", "get_url", "debug"):
            # these are "real actions" — always count as changed on first touch,
            # idempotent if the exact same action was already recorded
            key = f"{module}:{json.dumps(params, sort_keys=True)}"
            done = st.setdefault("actions", set())
            if key in done:
                return False, f"{module} already applied"
            done.add(key)
            return True, f"{module}: ok"
        return True, f"ran {module}"

    def _play_hosts(self, hosts_spec):
        # hosts: "web" | "all" | "web,db" | explicit list
        result = []
        for grp in [h.strip() for h in hosts_spec.split(",")]:
            if grp in self.inventory:
                result.extend(self.inventory[grp])
            elif grp == "all":
                for g in self.inventory.values():
                    result.extend(g)
            else:
                result.append(grp)
        return sorted(set(result))

    def run(self, rest):
        parts = rest.split()
        if not parts:
            return [], ["usage: ansible-playbook <playbook.yml>"]
        # strip flags like -i <file> / --tags <t>
        playbook = None
        tags = None
        i = 0
        argv = parts
        while i < len(argv):
            a = argv[i]
            if a in ("-i", "--inventory"):
                inv = argv[i + 1] if i + 1 < len(argv) else "hosts.ini"
                self._load_inventory(inv)
                i += 2
                continue
            if a in ("--tags", "-t"):
                tags = argv[i + 1] if i + 1 < len(argv) else None
                i += 2
                continue
            if not a.startswith("-"):
                playbook = a
            i += 1
        if not playbook:
            return [], ["ansible-playbook: no playbook given"]
        p = self.fs._resolve(playbook)
        if p not in self.fs.files:
            return [], [f"ERROR! the playbook: {playbook} could not be found"]
        self._load_inventory("hosts.ini")
        data = yaml_parse(self.fs.files[p])
        if not isinstance(data, list):
            return [], ["ERROR! playbook must be a list of plays"]
        events = []
        self.handlers_fired = []
        for play in data:
            if not isinstance(play, dict):
                continue
            name = play.get("name", "unnamed")
            hosts = self._play_hosts(str(play.get("hosts", "all")))
            tasks = play.get("tasks", [])
            handlers = play.get("handlers", [])
            notify = {}  # handler-name -> set of hosts to run it on
            for task in tasks:
                if not isinstance(task, dict):
                    continue
                tname = task.get("name", "unnamed")
                if tags and tname not in str(tags).split(","):
                    continue
                mod = next((k for k in task if k not in ("name", "notify", "tags")), None)
                if mod is None:
                    continue
                params = task.get(mod, {}) or {}
                for host in hosts:
                    changed, msg = self._module(host, mod, params)
                    events.append({"play": name, "task": tname, "host": host,
                                   "changed": changed, "msg": msg})
                    if changed and task.get("notify"):
                        notify.setdefault(task["notify"], set()).add(host)
            # run handlers on the hosts that notified them
            for hdl in handlers:
                if not isinstance(hdl, dict):
                    continue
                hname = hdl.get("name", "")
                if hname not in notify:
                    continue
                mod = next((k for k in hdl if k != "name"), None)
                if mod is None:
                    continue
                params = hdl.get(mod, {}) or {}
                for host in notify[hname]:
                    changed, msg = self._module(host, mod, params)
                    events.append({"play": name, "task": f"HANDLER: {hname}",
                                   "host": host, "changed": changed, "msg": msg})
                    self.handlers_fired.append(hname)
        return self._render_events(events), []

    def _load_inventory(self, invfile):
        p = self.fs._resolve(invfile)
        if p in self.fs.files:
            groups = ini_parse(self.fs.files[p])
            if groups:
                self.inventory = groups
                return
        self.inventory = {"web": ["web-1", "web-2"], "db": ["db-1"],
                          "all": ["web-1", "web-2", "db-1"]}

    def _render_events(self, events):
        if not events:
            return ["PLAY [no hosts matched] ***************"]
        out = []
        cur_play = None
        cur_task = None
        for e in events:
            if e["play"] != cur_play:
                out.append(f"PLAY [{e['play']}] *******************************")
                cur_play = e["play"]
                cur_task = None
            if e["task"] != cur_task:
                out.append(f"TASK [{e['task']}] ******************************")
                cur_task = e["task"]
            status = "changed" if e["changed"] else "ok"
            out.append(f"{status}: [{e['host']}]  {e['msg']}")
        # recap
        out.append("PLAY RECAP *****************************************")
        hosts = sorted({e["host"] for e in events})
        for h in hosts:
            ok = sum(1 for e in events if e["host"] == h and not e["changed"])
            ch = sum(1 for e in events if e["host"] == h and e["changed"])
            out.append(f"{h} : ok={ok} changed={ch} unreachable=0 failed=0")
        return out


# ---- CI/CD pipeline (simulated) ----------------------------------------------

class Pipeline:
    def __init__(self, fs):
        self.fs = fs
        self.runs = []     # {"id", "commit", "stages": [{"name","status"}], "log": [lines]}

    def _workflow(self):
        p = self.fs._resolve(".github/workflows/ci.yml")
        return self.fs.files.get(p, "")

    def _stages(self):
        wf = self._workflow()
        if not wf:
            return [{"name": "build", "cmd": "echo build"}]
        stages = []
        data = yaml_parse(wf)
        jobs = (data or {}).get("jobs", {}) if isinstance(data, dict) else {}
        for name, job in (jobs.items() if isinstance(jobs, dict) else []):
            steps = job.get("steps", []) if isinstance(job, dict) else []
            for st in steps:
                if isinstance(st, dict) and st.get("run"):
                    stages.append({"name": st.get("name", "run"), "cmd": st["run"]})
                elif isinstance(st, dict) and st.get("uses"):
                    stages.append({"name": st.get("name", st["uses"]), "cmd": "uses:" + st["uses"]})
        return stages or [{"name": "build", "cmd": "echo build"}]

    def run(self, rest):
        parts = rest.split()
        if not parts:
            return [], ["usage: ci <run|status|logs>"]
        cmd = parts[0]
        if cmd == "run":
            return self._run_pipeline("manual")
        if cmd == "status":
            if not self.runs:
                return ["no pipeline runs yet"], []
            out = []
            for r in self.runs[-5:]:
                ok = all(s["status"] == "pass" for s in r["stages"])
                out.append(f"#{r['id']}  commit {r['commit']}  {'green' if ok else 'red'}")
            return out, []
        if cmd == "logs":
            rid = parts[1] if len(parts) > 1 else (self.runs[-1]["id"] if self.runs else None)
            for r in self.runs:
                if str(r["id"]) == str(rid):
                    return r["log"], []
            return [], ["no such run"]
        return [], [f"ci: unknown command '{cmd}'"]

    def _run_pipeline(self, commit):
        rid = len(self.runs) + 1
        stages = self._stages()
        log = [f"Run #{rid} — commit {commit}", "=" * 40]
        built = []
        for st in stages:
            name, cmd = st["name"], st["cmd"]
            log.append(f"▶ {name}")
            status = "pass"
            if cmd.startswith("uses:"):
                log.append(f"  → {cmd}")
            elif cmd.startswith("python3") or cmd.startswith("pytest"):
                # actually run the test file so a broken test fails the build
                file = cmd.split()[1] if cmd.startswith("python3") else cmd.split()[1]
                fp = self.fs._resolve(file)
                if fp in self.fs.files:
                    stdout, stderr = run_lesson_code(self.fs.files[fp])
                    if stderr.strip() or "Error" in stdout or "Traceback" in stdout:
                        status = "fail"
                        log += [("  " + l) for l in stderr.strip().splitlines()[:4]]
                    else:
                        log += [("  " + l) for l in stdout.strip().splitlines()[:4]]
                else:
                    status = "fail"
                    log.append(f"  {file}: No such file or directory")
            else:
                log.append(f"  → {cmd}")
            if status == "pass":
                log.append(f"  ✓ {name} passed")
            else:
                log.append(f"  ✗ {name} failed")
            built.append({"name": name, "status": status})
        run = {"id": rid, "commit": commit, "stages": built, "log": log}
        self.runs.append(run)
        ok = all(s["status"] == "pass" for s in built)
        log.append("=" * 40)
        log.append(f"RESULT: {'✓ green' if ok else '✗ red'}")
        return log, []


# ---- CloudLab: the one orchestrator the trainer talks to --------------------

_BOTO3_STUB = '''\
"""A tiny offline stand-in for boto3 — enough S3 + EC2 to teach the API.

Reads state from $BOTO3_STATE (JSON), applies the learner's calls, and writes
the result back on exit. No network, no real AWS, deterministic."""
import json, os, atexit

_STATE_PATH = os.environ.get("BOTO3_STATE", "")
_state = None


def _get_state():
    global _state
    if _state is None:
        with open(_STATE_PATH) as f:
            _state = json.load(f)
        atexit.register(_flush)
    return _state


def _flush():
    global _state
    if _state is not None:
        with open(_STATE_PATH, "w") as f:
            json.dump(_state, f)


class _Body:
    def __init__(self, content):
        self._content = content
    def read(self):
        return self._content


class _S3Client:
    def __init__(self, s):
        self.s = s
    def list_buckets(self):
        return {"Buckets": [{"Name": n} for n in self.s["buckets"]]}
    def create_bucket(self, Bucket):
        if Bucket in self.s["buckets"]:
            raise Exception("BucketAlreadyExists: " + Bucket)
        self.s["buckets"][Bucket] = {}
        return {"Location": "/" + Bucket}
    def put_object(self, Bucket, Key, Body=""):
        if Bucket not in self.s["buckets"]:
            raise Exception("NoSuchBucket: " + Bucket)
        self.s["buckets"][Bucket][Key] = str(Body)
        return {"ETag": '"abc"'}
    def get_object(self, Bucket, Key):
        if Bucket not in self.s["buckets"] or Key not in self.s["buckets"][Bucket]:
            raise Exception("NoSuchKey: " + Key)
        return {"Body": _Body(self.s["buckets"][Bucket][Key])}
    def list_objects_v2(self, Bucket):
        if Bucket not in self.s["buckets"]:
            raise Exception("NoSuchBucket: " + Bucket)
        return {"Contents": [{"Key": k} for k in sorted(self.s["buckets"][Bucket])]}
    def delete_object(self, Bucket, Key):
        self.s["buckets"].get(Bucket, {}).pop(Key, None)
        return {}
    def delete_bucket(self, Bucket):
        if Bucket in self.s["buckets"] and self.s["buckets"][Bucket]:
            raise Exception("BucketNotEmpty: " + Bucket)
        self.s["buckets"].pop(Bucket, None)
        return {}


class _Ec2Client:
    def __init__(self, s):
        self.s = s
    def run_instances(self, ImageId, InstanceType="t3.micro", MinCount=1, MaxCount=1):
        ids = []
        for _ in range(int(MinCount)):
            iid = "i-%04d" % self.s["next_inst"]
            self.s["next_inst"] += 1
            self.s["instances"][iid] = {"ImageId": ImageId, "InstanceType": InstanceType,
                                        "State": {"Name": "running"}}
            ids.append(iid)
        return {"Instances": [{"InstanceId": i, "State": {"Name": "running"}} for i in ids]}
    def describe_instances(self):
        out = []
        for iid, inst in self.s["instances"].items():
            out.append({"InstanceId": iid, "ImageId": inst["ImageId"],
                        "InstanceType": inst["InstanceType"], "State": {"Name": inst["State"]["Name"]}})
        return {"Reservations": [{"Instances": out}]}
    def terminate_instances(self, InstanceIds):
        for iid in InstanceIds:
            if iid in self.s["instances"]:
                self.s["instances"][iid]["State"]["Name"] = "terminated"
        return {"TerminatingInstances": [{"InstanceId": i} for i in InstanceIds]}
    def stop_instances(self, InstanceIds):
        for iid in InstanceIds:
            if iid in self.s["instances"]:
                self.s["instances"][iid]["State"]["Name"] = "stopped"
        return {"StoppingInstances": [{"InstanceId": i} for i in InstanceIds]}
    def start_instances(self, InstanceIds):
        for iid in InstanceIds:
            if iid in self.s["instances"]:
                self.s["instances"][iid]["State"]["Name"] = "running"
        return {"StartingInstances": [{"InstanceId": i} for i in InstanceIds]}


class _Bucket:
    def __init__(self, s, name):
        self.s, self.name = s, name
    def create(self):
        if self.name in self.s["buckets"]:
            raise Exception("BucketAlreadyExists: " + self.name)
        self.s["buckets"][self.name] = {}
        return self
    def put_object(self, Key, Body=""):
        if self.name not in self.s["buckets"]:
            raise Exception("NoSuchBucket: " + self.name)
        self.s["buckets"][self.name][Key] = str(Body)
        return {"ETag": '"abc"'}


class _Object:
    def __init__(self, s, bucket, key):
        self.s, self.bucket, self.key = s, bucket, key
    def get(self):
        if self.bucket not in self.s["buckets"] or self.key not in self.s["buckets"][self.bucket]:
            raise Exception("NoSuchKey: " + self.key)
        return {"Body": _Body(self.s["buckets"][self.bucket][self.key])}
    def put(self, Body=""):
        if self.bucket not in self.s["buckets"]:
            raise Exception("NoSuchBucket: " + self.bucket)
        self.s["buckets"][self.bucket][self.key] = str(Body)
        return {"ETag": '"abc"'}


class _LambdaClient:
    def __init__(self, s):
        self.s = s
    def create_function(self, FunctionName, Runtime="python3.11", Role="", Handler="", Code=None):
        code = ""
        if Code and "ZipFile" in Code:
            zf = Code["ZipFile"]
            code = zf.decode() if isinstance(zf, bytes) else str(zf)
        self.s["lambda_fns"][FunctionName] = {"code": code, "runtime": Runtime, "handler": Handler}
        return {"FunctionArn": "arn:aws:lambda:us-east-1:123456789012:function:" + FunctionName}
    def invoke(self, FunctionName, Payload="{}"):
        fn = self.s["lambda_fns"].get(FunctionName)
        if not fn:
            raise Exception("ResourceNotFoundException: " + FunctionName)
        func = fn["handler"].split(".")[-1]
        code = fn["code"] + chr(10) + "print(" + func + "({}, None))"
        import subprocess, sys as _sys
        r = subprocess.run([_sys.executable, "-c", code], capture_output=True, text=True, timeout=10)
        return {"StatusCode": 200, "Payload": r.stdout}
    def list_functions(self):
        return {"Functions": [{"FunctionName": n} for n in sorted(self.s["lambda_fns"])]}


class _DynamoClient:
    def __init__(self, s):
        self.s = s
    def create_table(self, TableName, KeySchema=None, AttributeDefinitions=None, BillingMode="PAY_PER_REQUEST"):
        self.s["dynamo_tables"].setdefault(TableName, [])
        return {"TableDescription": {"TableName": TableName, "TableStatus": "ACTIVE"}}
    def put_item(self, TableName, Item):
        self.s["dynamo_tables"].setdefault(TableName, []).append(dict(Item))
        return {}
    def get_item(self, TableName, Key):
        for it in self.s["dynamo_tables"].get(TableName, []):
            if all(it.get(k) == v for k, v in Key.items()):
                return {"Item": dict(it)}
        return {}
    def scan(self, TableName):
        items = self.s["dynamo_tables"].get(TableName, [])
        return {"Items": [dict(it) for it in items], "Count": len(items)}
    def list_tables(self):
        return {"TableNames": list(self.s["dynamo_tables"].keys())}


class _DynamoTable:
    def __init__(self, s, name):
        self.s, self.name = s, name
    def put_item(self, Item):
        self.s["dynamo_tables"].setdefault(self.name, []).append(dict(Item))
        return {}
    def get_item(self, Key):
        for it in self.s["dynamo_tables"].get(self.name, []):
            if all(it.get(k) == v for k, v in Key.items()):
                return {"Item": dict(it)}
        return {}
    def scan(self):
        items = self.s["dynamo_tables"].get(self.name, [])
        return {"Items": [dict(it) for it in items], "Count": len(items)}


class _IamClient:
    def __init__(self, s):
        self.s = s
    def create_user(self, UserName):
        if UserName not in self.s["iam_users"]:
            self.s["iam_users"].append(UserName)
        return {"User": {"UserName": UserName}}
    def create_role(self, RoleName, AssumeRolePolicyDocument="{}"):
        self.s["iam_roles"][RoleName] = {"policies": []}
        return {"Role": {"RoleName": RoleName}}
    def create_policy(self, PolicyName, PolicyDocument="{}"):
        arn = "arn:aws:iam::123456789012:policy/" + PolicyName
        self.s["iam_policies"][PolicyName] = arn
        return {"Policy": {"Arn": arn}}
    def attach_role_policy(self, RoleName, PolicyArn):
        if RoleName in self.s["iam_roles"]:
            self.s["iam_roles"][RoleName]["policies"].append(PolicyArn)
        return {}
    def list_users(self):
        return {"Users": [{"UserName": u} for u in sorted(self.s["iam_users"])]}


class _Resource:
    def __init__(self, s):
        self.s = s
    def Bucket(self, name):
        return _Bucket(self.s, name)
    def Object(self, bucket, key):
        return _Object(self.s, bucket, key)
    def Table(self, name):
        return _DynamoTable(self.s, name)


def client(name, **kw):
    s = _get_state()
    if name == "s3":
        return _S3Client(s)
    if name == "ec2":
        return _Ec2Client(s)
    if name == "lambda":
        return _LambdaClient(s)
    if name == "dynamodb":
        return _DynamoClient(s)
    if name == "iam":
        return _IamClient(s)
    raise Exception("UnknownServiceError: " + name)


def resource(name, **kw):
    s = _get_state()
    if name == "s3":
        return _Resource(s)
    if name == "dynamodb":
        return _Resource(s)
    raise Exception("UnknownServiceError: " + name)
'''


def _run_boto3_script(code, state):
    """Run a learner's boto3 script against the simulated AWS state in a
    subprocess, returning (stdout, stderr, new_state)."""
    with tempfile.TemporaryDirectory() as d:
        with open(os.path.join(d, "boto3.py"), "w") as f:
            f.write(_BOTO3_STUB)
        with open(os.path.join(d, "script.py"), "w") as f:
            f.write(code)
        state_path = os.path.join(d, "state.json")
        with open(state_path, "w") as f:
            json.dump(state, f)
        env = dict(os.environ)
        env["PYTHONPATH"] = d + os.pathsep + env.get("PYTHONPATH", "")
        env["BOTO3_STATE"] = state_path
        try:
            r = subprocess.run([sys.executable, os.path.join(d, "script.py")],
                               capture_output=True, text=True, timeout=10,
                               cwd=d, env=env)
        except subprocess.TimeoutExpired:
            return "", "[timed out]", None
        try:
            with open(state_path) as f:
                new_state = json.load(f)
        except Exception:
            new_state = None
        return r.stdout, r.stderr, new_state


class CloudLab:
    """One offline 'developer environment': local bash + git + docker + AWS +
    terraform + ansible + CI/CD. `run(cmdline)` executes one line and returns
    (out_lines, err_lines), exactly like ShellFS.run."""

    def __init__(self):
        self.fs = ShellFS()
        self.git = GitRepo(self.fs)
        self.docker = DockerEnv(self.fs)
        self.aws = AwsEnv(self.fs)
        self.tf = TerraformEnv(self.fs)
        self.ansible = AnsibleEnv(self.fs)
        self.pipeline = Pipeline(self.fs)
        self.k8s = K8sEnv(self.fs)
        self.history = []

    def run(self, cmdline):
        cmdline = cmdline.strip()
        if not cmdline:
            return [], []
        self.history.append(cmdline)
        cmd = cmdline.split()[0]
        rest = cmdline[len(cmd):].strip()
        if cmd == "git":
            out, err = self.git.run(rest)
            if cmdline.startswith("git commit"):
                # every commit triggers a CI run (the "push to CI" loop)
                self.pipeline._run_pipeline(self.git.commits[-1]["hash"] if self.git.commits else "HEAD")
            return out, err
        if cmd == "docker":
            return self.docker.run(rest)
        if cmd == "aws":
            return self.aws.run(rest)
        if cmd == "terraform":
            return self.tf.run(rest)
        if cmd in ("ansible-playbook", "ansible"):
            return self.ansible.run(rest)
        if cmd == "kubectl":
            return self.k8s.run(rest)
        if cmd == "ci":
            return self.pipeline.run(rest)
        if cmd == "python3" and self._uses_boto3(cmdline):
            return self._run_boto3(cmdline)
        return self.fs.run(cmdline)

    def _uses_boto3(self, cmdline):
        parts = cmdline.split()
        if len(parts) < 2:
            return False
        p = self.fs._resolve(parts[1])
        return p in self.fs.files and "boto3" in self.fs.files[p]

    def _run_boto3(self, cmdline):
        parts = cmdline.split()
        p = self.fs._resolve(parts[1])
        code = self.fs.files[p]
        state = {"buckets": self.aws.buckets, "instances": self.aws.instances,
                 "next_inst": self.aws.next_inst,
                 "lambda_fns": self.aws.lambda_fns,
                 "dynamo_tables": self.aws.dynamo_tables,
                 "iam_users": sorted(self.aws.iam_users),
                 "iam_roles": self.aws.iam_roles,
                 "iam_policies": self.aws.iam_policies}
        stdout, stderr, new_state = _run_boto3_script(code, state)
        if new_state is not None:
            self.aws.buckets = new_state["buckets"]
            self.aws.instances = new_state["instances"]
            self.aws.next_inst = new_state["next_inst"]
            self.aws.lambda_fns = new_state["lambda_fns"]
            self.aws.dynamo_tables = new_state["dynamo_tables"]
            self.aws.iam_users = set(new_state["iam_users"])
            self.aws.iam_roles = new_state["iam_roles"]
            self.aws.iam_policies = new_state["iam_policies"]
        out = stdout.rstrip("\n").split("\n") if stdout.rstrip("\n") else []
        err = stderr.rstrip("\n").split("\n") if stderr.strip() else []
        return out, err


