def _net_topic_qs(concept: str) -> list:
    """All questions that belong to a topic: the concept itself, anything
    prefixed with it (port-SSH …), plus the explicit extras map."""
    stems = {concept, concept.rstrip("s")}
    qs = [q for q in NET_QUESTIONS
          if q["concept"] in stems
          or any(q["concept"].startswith(s + "-") for s in stems)]
    seen = {id(q) for q in qs}
    for extra in NET_TOPIC_CONCEPTS.get(concept, []):
        ex_stems = {extra, extra.rstrip("s")}
        for q in NET_QUESTIONS:
            if (q["concept"] in ex_stems
                    or any(q["concept"].startswith(s + "-")
                           for s in ex_stems)) and id(q) not in seen:
                seen.add(id(q))
                qs.append(q)
    return qs


def _net_alt_question(q: dict, asked: list) -> dict:
    """A DIFFERENT question about the same concept (the retrain re-ask).  If
    the concept only has one question, fall back to a same-family concept,
    then to any other question of the same level.  Every question already in
    `asked` is excluded, so re-asks never cycle back to something seen."""
    same = [x for x in _net_concept_questions(q["concept"])
            if x is not q and all(x is not a for a in asked)]
    if same:
        return same[len(asked) % len(same)]
    fam = [x for x in NET_QUESTIONS
           if x["concept"].split("-")[0] == q["concept"].split("-")[0]
           and x is not q
           and all(x is not a for a in asked)]
    if fam:
        return fam[len(asked) % len(fam)]
    level_pool = [x for x in _net_pool_by_level(q["level"])
                  if x is not q and all(x is not a for a in asked)]
    return level_pool[len(asked) % len(level_pool)]


# ---- animated network diagrams ------------------------------------------- #
# Each returns a list of Text frames (played on a timer while the voice talks).

def _net_frame(title: str, lines: list, hi: int = -1) -> Text:
    t = Text()
    t.append(title, style="bold #7dd3fc")
    t.append("\n\n")
    for i, ln in enumerate(lines):
        if i == hi:
            t.append("▸ ", style="bold #fbbf24")
            t.append(ln, style="bold #fbbf24")
        else:
            t.append("  ")
            t.append(ln, style="#d5d5d5")
        t.append("\n")
    return t


# ---- the rich, animated diagram scenes ------------------------------------ #
# A shared palette + tiny helpers, then one scene per topic: real boxes,
# colored parts, and a packet token that actually moves across the wires.

_NET_HOST = "#7dd3fc"
_NET_SW = "#fbbf24"
_NET_RT = "#22c55e"
_NET_WIRE = "#6b7280"
_NET_PKT = "#fb923c"
_NET_BAD = "#f87171"
_NET_DIM = "#8b8b95"
_NET_TXT = "#d5d5d5"


def _net_row(parts, pad=2):
    """One diagram row built from (text, style) parts, left-padded."""
    t = Text()
    t.append(" " * pad)
    for text, style in parts:
        if text:
            t.append(text, style=style or _NET_TXT)
    return t


def _net_wire(pos, length):
    """A link line with the packet token `pos` cells along it."""
    pos = max(0, min(pos, length - 1))
    return _net_row([("─" * pos, _NET_WIRE), ("●", "bold " + _NET_PKT),
                     ("─" * (length - pos - 1), _NET_WIRE)])


def _net_scene(title, rows, hi=None, foot=None):
    """One frame: title, rows (Text), an optional ▸ highlight row, a footer."""
    t = Text()
    t.append(title, style="bold #7dd3fc")
    t.append("\n\n")
    for i, r in enumerate(rows):
        if i == hi:
            t.append("▸ ", style="bold #fbbf24")
        else:
            t.append("  ")
        t.append_text(r)
        t.append("\n")
    if foot:
        t.append("\n")
        t.append("  ")
        t.append(foot, style=_NET_DIM)
    return t


